<?php
$pdo=db();$tab=(string)($_GET['tab']??'accounts');if(!in_array($tab,['accounts','schedules','transactions'],true))$tab='accounts';$canManage=in_array($user['role'],['Administrator','Head','Bursar'],true);
$terms=$pdo->query('SELECT id,academic_year,term_number,name,starts_on,ends_on,is_current FROM school_terms ORDER BY is_current DESC,academic_year DESC,term_number DESC')->fetchAll();$categories=$pdo->query('SELECT id,code,name FROM fee_categories WHERE active=1 ORDER BY name')->fetchAll();
$currentTerm=null;foreach($terms as $term)if($term['is_current']){$currentTerm=$term;break;}
$termFilter=filter_var($_GET['term_id']??($currentTerm['id']??null),FILTER_VALIDATE_INT);
$termClause=$termFilter?' AND l.term_id=:term_id':'';$termParams=$termFilter?['term_id'=>$termFilter]:[];
$summaryStmt=$pdo->prepare("SELECT currency,SUM(CASE WHEN transaction_type='Payment' THEN amount ELSE 0 END) collected,SUM(CASE WHEN transaction_type='Payment' THEN -amount ELSE amount END) balance FROM fee_ledger l WHERE 1=1 $termClause GROUP BY currency");$summaryStmt->execute($termParams);$feeSummary=['USD'=>['collected'=>0.0,'balance'=>0.0],'ZiG'=>['collected'=>0.0,'balance'=>0.0]];foreach($summaryStmt->fetchAll() as $row)$feeSummary[$row['currency']]=['collected'=>(float)$row['collected'],'balance'=>(float)$row['balance']];
$q=trim((string)($_GET['q']??''));$formFilter=filter_var($_GET['form']??null,FILTER_VALIDATE_INT);$studentId=filter_var($_GET['student_id']??null,FILTER_VALIDATE_INT);
$receiptId=filter_var($_GET['receipt']??null,FILTER_VALIDATE_INT);$receipt=null;
if($receiptId){$stmt=$pdo->prepare('SELECT l.*,s.admission_no,s.first_name,s.last_name,c.name AS category_name,u.full_name AS recorded_name,rev.id AS reversal_id,p.school_name,p.school_code,p.address AS school_address,p.phone AS school_phone FROM fee_ledger l JOIN students s ON s.id=l.student_id LEFT JOIN fee_categories c ON c.id=l.category_id LEFT JOIN users u ON u.id=l.recorded_by LEFT JOIN fee_ledger rev ON rev.reverses_id=l.id CROSS JOIN school_profile p WHERE l.id=:id AND l.receipt_no IS NOT NULL AND p.id=1');$stmt->execute(['id'=>$receiptId]);$receipt=$stmt->fetch()?:null;}
$student=null;$ledgerRows=[];$balance=['USD'=>0.0,'ZiG'=>0.0];
if($studentId){$stmt=$pdo->prepare('SELECT id,admission_no,first_name,last_name,form_level,stream,status FROM students WHERE id=:id');$stmt->execute(['id'=>$studentId]);$student=$stmt->fetch()?:null;if($student){$stmt=$pdo->prepare("SELECT l.*,c.name AS category_name,u.full_name AS recorded_name,r.id AS reversal_id,orig.receipt_no AS original_receipt FROM fee_ledger l LEFT JOIN fee_categories c ON c.id=l.category_id LEFT JOIN users u ON u.id=l.recorded_by LEFT JOIN fee_ledger r ON r.reverses_id=l.id LEFT JOIN fee_ledger orig ON orig.id=l.reverses_id WHERE l.student_id=:id ORDER BY l.transaction_date DESC,l.id DESC");$stmt->execute(['id'=>$studentId]);$ledgerRows=$stmt->fetchAll();foreach($ledgerRows as $l){$balance[$l['currency']]+=$l['transaction_type']==='Payment'?-(float)$l['amount']:(float)$l['amount'];}}}
$receiptRows=$pdo->query("SELECT l.id,l.student_id,l.transaction_type,l.description,l.amount,l.currency,l.receipt_no,l.payment_method,l.transaction_date,l.external_reference,s.admission_no,s.first_name,s.last_name,r.id AS reversal_id FROM fee_ledger l JOIN students s ON s.id=l.student_id LEFT JOIN fee_ledger r ON r.reverses_id=l.id WHERE l.transaction_type='Payment' AND l.receipt_no IS NOT NULL ORDER BY l.id DESC LIMIT 50")->fetchAll();
$schedules=$pdo->query('SELECT fs.*,t.name AS term_name,t.academic_year,c.name AS category_name,u.full_name AS creator FROM fee_schedules fs JOIN school_terms t ON t.id=fs.term_id JOIN fee_categories c ON c.id=fs.category_id LEFT JOIN users u ON u.id=fs.created_by ORDER BY fs.id DESC')->fetchAll();
$txnSql="SELECT l.id,l.student_id,l.transaction_type,l.description,l.amount,l.currency,l.receipt_no,l.payment_method,l.external_reference,l.transaction_date,l.reverses_id,l.reversal_reason,s.admission_no,s.first_name,s.last_name,c.name AS category_name,r.id AS reversal_id FROM fee_ledger l JOIN students s ON s.id=l.student_id LEFT JOIN fee_categories c ON c.id=l.category_id LEFT JOIN fee_ledger r ON r.reverses_id=l.id WHERE 1=1 $termClause";
$txnParams=$termParams;if($q!==''){$txnSql.=' AND (s.first_name LIKE :q1 OR s.last_name LIKE :q2 OR s.admission_no LIKE :q3 OR l.receipt_no LIKE :q4)';$txnParams+=['q1'=>'%'.$q.'%','q2'=>'%'.$q.'%','q3'=>'%'.$q.'%','q4'=>'%'.$q.'%'];}$txnSql.=' ORDER BY l.transaction_date DESC,l.id DESC LIMIT 100';$txnStmt=$pdo->prepare($txnSql);$txnStmt->execute($txnParams);$transactions=$txnStmt->fetchAll();
$accountWhere="WHERE s.status IN ('Active','Graduated','Transferred','Withdrawn')";$accountParams=[];if($q!==''){$accountWhere.=' AND (s.first_name LIKE :q1 OR s.last_name LIKE :q2 OR s.admission_no LIKE :q3)';$accountParams+=['q1'=>'%'.$q.'%','q2'=>'%'.$q.'%','q3'=>'%'.$q.'%'];}if($formFilter!==false&&$formFilter>=1&&$formFilter<=6){$accountWhere.=' AND s.form_level=:form';$accountParams['form']=$formFilter;}
$accountStmt=$pdo->prepare("SELECT s.id,s.admission_no,s.first_name,s.last_name,s.form_level,s.stream,COALESCE(SUM(CASE WHEN l.currency='USD' THEN CASE WHEN l.transaction_type='Payment' THEN -l.amount ELSE l.amount END ELSE 0 END),0) usd_balance,COALESCE(SUM(CASE WHEN l.currency='ZiG' THEN CASE WHEN l.transaction_type='Payment' THEN -l.amount ELSE l.amount END ELSE 0 END),0) zig_balance FROM students s LEFT JOIN fee_ledger l ON l.student_id=s.id $accountWhere GROUP BY s.id,s.admission_no,s.first_name,s.last_name,s.form_level,s.stream ORDER BY s.last_name,s.first_name LIMIT 250");$accountStmt->execute($accountParams);$accountRows=$accountStmt->fetchAll();
?>
