  <section class="receipt-card"><div class="receipt-header"><div><div class="brand-mark">M</div></div><div><h2><?= h($receipt['school_name']) ?></h2><?php if($receipt['school_code']): ?><p><?= h($receipt['school_code']) ?></p><?php endif; ?><?php if($receipt['school_address']): ?><p><?= nl2br(h($receipt['school_address'])) ?></p><?php endif; ?><?php if($receipt['school_phone']): ?><p><?= h($receipt['school_phone']) ?></p><?php endif; ?></div><span class="receipt-label">OFFICIAL RECEIPT</span></div><div class="receipt-rule"></div><div class="receipt-grid"><div><small>Receipt number</small><b><?= h($receipt['receipt_no']) ?></b></div><div><small>Date paid</small><b><?= h(date('d M Y',strtotime($receipt['transaction_date']))) ?></b></div><div><small>Received from</small><b><?= h($receipt['first_name'].' '.$receipt['last_name']) ?></b></div><div><small>Admission number</small><b><?= h($receipt['admission_no']) ?></b></div><div><small>Payment method</small><b><?= h($receipt['payment_method']?:'Not recorded') ?></b></div><div><small>Reference</small><b><?= h($receipt['external_reference']?:'—') ?></b></div></div><table class="receipt-lines"><thead><tr><th>Description</th><th>Category</th><th>Amount</th></tr></thead><tbody><tr><td><?= h($receipt['description']) ?></td><td><?= h($receipt['category_name']?:'—') ?></td><td><?= h($receipt['currency']) ?> <?= number_format((float)$receipt['amount'],2) ?></td></tr></tbody><tfoot><tr><th colspan="2">Total received</th><th><?= h($receipt['currency']) ?> <?= number_format((float)$receipt['amount'],2) ?></th></tr></tfoot></table><?php if($receipt['exchange_rate']): ?><p class="receipt-note">Recorded exchange rate: <?= h(number_format((float)$receipt['exchange_rate'],6)) ?></p><?php endif; ?><?php if($receipt['reversal_id']): ?><div class="alert alert-error">This receipt was reversed by transaction #<?= (int)$receipt['reversal_id'] ?>. It is retained for audit history.</div><?php endif; ?><div class="receipt-signature"><span>Received by: <?= h($receipt['recorded_name']?:'School bursar') ?></span><span>Thank you.</span></div></section>
