  <div class="page-heading"><div><div class="eyebrow">LEARNER ACCOUNT</div><h1><?= h($student['first_name'].' '.$student['last_name']) ?></h1><p class="subheading"><?= h($student['admission_no']) ?> · Form <?= (int)$student['form_level'] ?><?= $student['stream']?' · '.h($student['stream']):'' ?></p></div><div class="page-actions"><a class="outline-button" href="?page=fees">← All accounts</a></div></div>
  <section class="stat-strip"><div><span>USD balance</span><b>$<?= number_format($balance['USD'],2) ?></b></div><div><span>ZiG balance</span><b>ZiG <?= number_format($balance['ZiG'],2) ?></b></div><div><span>USD outstanding</span><b><?= $balance['USD']>0?'Due':'Credit / settled' ?></b></div><div><span>Account entries</span><b><?= count($ledgerRows) ?></b></div></section>
  <?php if($canManage): ?><section class="panel settings-panel"><h2>Record a transaction</h2><p>Payments create a numbered receipt. Charges and adjustments remain on the immutable ledger.</p><form method="post" action="actions/fee_transaction_save.php" class="inline-form fee-transaction-form"><?= csrf_field() ?><input type="hidden" name="student_id" value="<?= (int)$student['id'] ?>"><label>Type<select name="transaction_type"><option>Payment</option><option>Charge</option><option>Adjustment</option></select></label><label>Description<input name="description" required maxlength="180" placeholder="School fees / levy"></label><label>Category<select name="category_id"><option value="">Uncategorised</option><?php foreach($categories as $category): ?><option value="<?= (int)$category['id'] ?>"><?= h($category['name']) ?></option><?php endforeach; ?></select></label><label>Amount<input type="number" name="amount" required step="0.01" placeholder="Positive amount; adjustment can be negative"></label><label>Currency<select name="currency"><option>USD</option><option>ZiG</option></select></label><label>Payment method<select name="payment_method"><option value="">Not applicable</option><?php foreach(['Cash','EcoCash','Bank transfer','Swipe','Other'] as $method): ?><option><?= h($method) ?></option><?php endforeach; ?></select></label><label>Exchange rate <span class="optional">Optional, for ZiG</span><input type="number" name="exchange_rate" step="0.000001" min="0.000001"></label><label>Transaction date<input type="date" name="transaction_date" value="<?= date('Y-m-d') ?>" max="<?= date('Y-m-d') ?>" required></label><label>Reference <span class="optional">Optional</span><input name="external_reference" maxlength="100"></label><label>Term<select name="term_id"><option value="">No term</option><?php foreach($terms as $term): ?><option value="<?= (int)$term['id'] ?>" <?= $term['is_current']?'selected':'' ?>><?= h($term['name']) ?> · <?= (int)$term['academic_year'] ?></option><?php endforeach; ?></select></label><button class="primary-button">Save transaction</button></form><p class="privacy-note">USD and ZiG remain separate balances. No exchange conversion is applied automatically; any recorded exchange rate is retained as transaction context.</p></section><?php endif; ?>
  <section class="panel learners-panel"><div class="panel-heading"><div><h2>Account ledger</h2><p>Charges, receipts, adjustments and reversals are shown in transaction order.</p></div></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Date</th><th>Entry</th><th>Category</th><th>Amount</th><th>Receipt</th><th>Method / reference</th><th>Action</th></tr></thead><tbody><?php foreach($ledgerRows as $entry): $amountSign=$entry['transaction_type']==='Payment'?'−':($entry['amount']<0?'−':'+'); ?><tr><td><?= h(date('d M Y',strtotime($entry['transaction_date']))) ?></td><td><?= h($entry['transaction_type']) ?> · <?= h($entry['description']) ?><?php if($entry['reverses_id']): ?><small class="reversal-label">Reversal of #<?= (int)$entry['reverses_id'] ?></small><?php endif; ?></td><td><?= h($entry['category_name']?:'—') ?></td><td><?= h($entry['currency']) ?> <?= $amountSign ?><?= number_format(abs((float)$entry['amount']),2) ?></td><td><?= $entry['receipt_no']?'<a class="text-button" href="?page=fees&receipt='.(int)$entry['id'].'">'.h($entry['receipt_no']).'</a>':'—' ?><?php if($entry['reversal_id']): ?><small class="reversal-label">Reversed</small><?php endif; ?></td><td><?= h($entry['payment_method']?:'—') ?><?= $entry['external_reference']?' · '.h($entry['external_reference']):'' ?></td><td><?php if($canManage&&!$entry['reversal_id']&&!$entry['reverses_id']): ?><form method="post" action="actions/fee_reverse.php" class="reverse-form"><?= csrf_field() ?><input type="hidden" name="transaction_id" value="<?= (int)$entry['id'] ?>"><input name="reason" required maxlength="200" placeholder="Reason to reverse"><button class="text-button">Reverse</button></form><?php endif; ?></td></tr><?php endforeach; if(!$ledgerRows): ?><tr><td colspan="7" class="empty-cell">No account transactions yet.</td></tr><?php endif; ?></tbody></table></div></section>
<?php else: ?>
