  <?php if($tab==='accounts'): ?><section class="panel learners-panel"><form class="list-toolbar" method="get" action="/"><input type="hidden" name="page" value="fees"><input type="hidden" name="tab" value="accounts"><div class="search-box"><span>⌕</span><input name="q" value="<?= h($q) ?>" placeholder="Search learner name or admission number"></div><div class="toolbar-right"><select class="select-control" name="form"><option value="">All forms</option><?php for($i=1;$i<=6;$i++): ?><option value="<?= $i ?>" <?= $formFilter===$i?'selected':'' ?>>Form <?= $i ?></option><?php endfor; ?></select><button class="outline-button">Search</button></div></form><div class="table-scroll"><table class="data-table"><thead><tr><th>Learner</th><th>Admission</th><th>Form</th><th>USD balance</th><th>ZiG balance</th><th></th></tr></thead><tbody><?php foreach($accountRows as $row): ?><tr><td><b><?= h($row['first_name'].' '.$row['last_name']) ?></b></td><td><?= h($row['admission_no']) ?></td><td>Form <?= (int)$row['form_level'] ?><?= $row['stream']?' · '.h($row['stream']):'' ?></td><td class="<?= (float)$row['usd_balance']<0?'credit-balance':'' ?>">$<?= number_format((float)$row['usd_balance'],2) ?></td><td class="<?= (float)$row['zig_balance']<0?'credit-balance':'' ?>">ZiG <?= number_format((float)$row['zig_balance'],2) ?></td><td><a class="text-button" href="?page=fees&student_id=<?= (int)$row['id'] ?>">Open account →</a></td></tr><?php endforeach; if(!$accountRows): ?><tr><td colspan="6" class="empty-cell">No learner accounts match.</td></tr><?php endif; ?></tbody></table></div></section>
