    <section class="panel learners-panel"><div class="panel-heading"><div><h2>Term fee schedules</h2><p>Apply each schedule once to create learner charges</p></div></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Term</th><th>Category</th><th>Form</th><th>Description</th><th>Amount</th><th>Due</th><th>Status</th><?php if($canManage): ?><th></th><?php endif; ?></tr></thead><tbody><?php foreach($schedules as $schedule): ?><tr><td><?= h($schedule['term_name']) ?> <?= (int)$schedule['academic_year'] ?></td><td><?= h($schedule['category_name']) ?></td><td><?= (int)$schedule['form_level']===0?'All forms':'Form '.(int)$schedule['form_level'] ?></td><td><?= h($schedule['description']) ?></td><td><?= h($schedule['currency']) ?> <?= number_format((float)$schedule['amount'],2) ?></td><td><?= $schedule['due_date']?h(date('d M Y',strtotime($schedule['due_date']))):'—' ?></td><td><span class="status-pill <?= $schedule['active']?'':'inactive' ?>"><?= $schedule['active']?'Active':'Inactive' ?></span></td><?php if($canManage): ?><td><form method="post" action="actions/fee_schedule_apply.php"><?= csrf_field() ?><input type="hidden" name="schedule_id" value="<?= (int)$schedule['id'] ?>"><button class="outline-button compact-button" <?= $schedule['active']?'':'disabled' ?>>Apply to learners</button></form></td><?php endif; ?></tr><?php endforeach; if(!$schedules): ?><tr><td colspan="<?= $canManage?8:7 ?>" class="empty-cell">No term fee schedules yet.</td></tr><?php endif; ?></tbody></table></div></section>
  <?php else: ?><section class="panel learners-panel"><form class="list-toolbar" method="get" action="/"><input type="hidden" name="page" value="fees"><input type="hidden" name="tab" value="transactions"><div class="search-box"><span>⌕</span><input name="q" value="<?= h($q) ?>" placeholder="Search learner, admission or receipt"></div><div class="toolbar-right"><select class="select-control" name="term_id"><option value="">All terms</option><?php foreach($terms as $term): ?><option value="<?= (int)$term['id'] ?>" <?= $termFilter===(int)$term['id']?'selected':'' ?>><?= h($term['name']) ?> · <?= (int)$term['academic_year'] ?></option><?php endforeach; ?></select><button class="outline-button">Filter</button></div></form><div class="table-scroll"><table class="data-table"><thead><tr><th>Date</th><th>Learner</th><th>Type</th><th>Description</th><th>Amount</th><th>Receipt / reference</th><th>Status</th></tr></thead><tbody><?php foreach($transactions as $entry): $displaySign=$entry['transaction_type']==='Payment'?'−':((float)$entry['amount']<0?'−':'+'); ?><tr><td><?= h(date('d M Y',strtotime($entry['transaction_date']))) ?></td><td><?= h($entry['first_name'].' '.$entry['last_name']) ?><small class="muted-cell"><?= h($entry['admission_no']) ?></small></td><td><?= h($entry['transaction_type']) ?></td><td><?= h($entry['description']) ?><?= $entry['reverses_id']?'<small class="reversal-label">Reversal of #'.(int)$entry['reverses_id'].'</small>':'' ?></td><td><?= h($entry['currency']) ?> <?= $displaySign.number_format(abs((float)$entry['amount']),2) ?></td><td><?= $entry['receipt_no']?'<a class="text-button" href="?page=fees&receipt='.(int)$entry['id'].'">'.h($entry['receipt_no']).'</a>':h($entry['external_reference']?:'—') ?></td><td><?= $entry['reversal_id']?'<span class="consent-pill revoked">Reversed</span>':'<span class="consent-pill granted">Posted</span>' ?></td></tr><?php endforeach; if(!$transactions): ?><tr><td colspan="7" class="empty-cell">No fee transactions found.</td></tr><?php endif; ?></tbody></table></div></section><?php endif; ?>
